    import sys
    import itertools

    def solve(N, K, A):
        total_sum = sum(A)
        if total_sum < K:
            return N

        unnecessary_count = 0

        for i in range(N):
            remaining_sum = total_sum - A[i]
            if remaining_sum >= K:
                unnecessary_count += 1
            else:
                for r in range(1, N):
                    for subset in itertools.combinations(A[:i] + A[i+1:], r):
                        if sum(subset) >= K:
                            break
                    else:
                        continue
                    break
                else:
                    unnecessary_count += 1

        return unnecessary_count

    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    K = int(data[1])
    A = list(map(int, data[2:]))

